-- PT107-S3-Q3. Batch 05.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch05$PT107-S3-Q3$batch05$ AND q.stimulus=$batch05$Land developer: By attempting to preserve endangered species that otherwise would become extinct during our lifetime, we are wasting money on species that will disappear over time regardless of our efforts. Paleontologists have established that extinction is the normal fate of species on the geological time scale of millions of years. Environmentalist: To claim that we should let species disappear because all species eventually die out makes about as much sense as arguing that we should not spend money to find a cure for cancer because all humans are inevitably mortal.$batch05$ AND q.prompt=$batch05$The method the environmentalist uses to object to the land developer's argument is to$batch05$ AND q.correct_choice=$batch05$D$batch05$) THEN RAISE EXCEPTION 'Question changed: PT107-S3-Q3'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch05$PT107-S3-Q3$batch05$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT107-S3-Q3'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch05$PT107-S3-Q3$batch05$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch05$Conclusion$batch05$, $batch05$(Environmentalist) The land developer's reasoning does not make sense.$batch05$), (1, $batch05$Evidence$batch05$, $batch05$By the same logic, we should not fund cancer research because all humans eventually die.$batch05$), (2, $batch05$Evaluate$batch05$, $batch05$The developer's logic is: everything in this group will die out eventually, so do not spend to save any of them now. The environmentalist keeps the logic exactly the same and drops it on a new subject, people with cancer. The result is obviously unacceptable, which shows the logic is broken.$batch05$), (3, $batch05$Goal$batch05$, $batch05$Applying the developer's reasoning to another case to reach an absurd conclusion.$batch05$)) v(position,label,body) WHERE q.qid=$batch05$PT107-S3-Q3$batch05$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch05$A$batch05$, $batch05$No dilemma is laid out.$batch05$), ($batch05$B$batch05$, $batch05$The environmentalist attacks the reasoning, not the developer.$batch05$), ($batch05$C$batch05$, $batch05$No call for more evidence.$batch05$), ($batch05$D$batch05$, $batch05$Same reasoning, different situation (cancer), unacceptable conclusion (do not fund a cure). That is the whole response.$batch05$), ($batch05$E$batch05$, $batch05$The environmentalist is arguing that money *should* be spent, not that it cannot solve the problem.$batch05$)) v(letter,body) WHERE q.qid=$batch05$PT107-S3-Q3$batch05$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
COMMIT;
